\section{Setup and notation}

\begin{definition}[Logarithmic embedding]
For an integer $n\ge 2$ set $\iota(n)=1/\log n$, and for integers $p,q\ge 2$ define $d(p,q)=|\iota(p)-\iota(q)|$.
\end{definition}

Since $|x-y|$ is the euclidean distance on $\mathbb{R}$, $d$ is exactly the metric induced on the primes by $\iota$, so all metric questions about $(\{\text{primes}\},d)$ are questions about the subset $\iota(\{\text{primes}\})\subseteq\mathbb{R}$, provided $\iota$ is injective.

\begin{lemma}[Antitonicity and injectivity]\label{lem:anti}
For integers $2\le p<q$ we have $\iota(q)<\iota(p)$. Hence $\iota$ is injective on $\{n\ge 2\}$, and $(\{\text{primes}\},d)$ is isometric to $\PP$ with the euclidean metric.
\end{lemma}

\begin{proof}
$\log$ is strictly increasing and positive on $[2,\infty)$, so $t\mapsto 1/\log t$ is strictly decreasing there, hence injective.
\end{proof}

\begin{definition}[Prime, twin, integer fractals]
\[
\PP=\iota(\{p \text{ prime}\}),\quad \TT=\iota(\{p: p,\,p+2 \text{ prime}\}),\quad \II=\iota(\{n\in\mathbb{N}: n\ge 2\}).
\]
\end{definition}

\begin{lemma}[Localisation]\label{lem:loc}
$\PP\subseteq\II\subseteq(0,1/\log 2]\subseteq[0,2]$.
\end{lemma}

\begin{proof}
For $n\ge 2$, $\log n\ge\log 2>1/2$, so $0<\iota(n)\le 1/\log 2<2$.
\end{proof}

\section{The Hausdorff side}

For $s\ge 0$ the $s$-dimensional Hausdorff measure of $S\subseteq\mathbb{R}$ is
$\mathcal{H}^s(S)=\lim_{\delta\to0}\inf\{\sum_i(\operatorname{diam}U_i)^s: S\subseteq\bigcup_i U_i,\ \operatorname{diam}U_i\le\delta\}$,
and $\dimH S=\inf\{s:\mathcal{H}^s(S)=0\}$.

\begin{theorem}[Hausdorff Dimension Theorem]\label{thm:dimH}
$\dimH\PP=0$. Moreover $\dimH\iota(T)=0$ for \emph{every} set $T$ of integers $\ge 2$; in particular $\dimH\TT=\dimH\II=0$.
\end{theorem}

\begin{proof}[Proof sketch]
$\PP$ is the image of a countable set, hence countable. Every countable subset of a metric space has Hausdorff dimension $0$: enumerating $S=\{x_1,x_2,\dots\}$ and covering $x_n$ by an interval of diameter $\delta 2^{-n}$ gives, for $s>0$, $\sum_n(\delta 2^{-n})^s=\delta^s/(2^s-1)\to0$ as $\delta\to0$, so $\mathcal{H}^s(S)=0$ for all $s>0$. The argument uses nothing about primality, which is the point.
\end{proof}

\begin{corollary}
$\dimH\PP\neq 1$, and there is no $\varepsilon\ge0$ with $\dimH\PP=1+\varepsilon$; the same holds for every subfamily of primes. The truth value of the twin prime conjecture cannot influence the Hausdorff dimension of any of these sets.
\end{corollary}

\begin{theorem}[Compactification]\label{thm:compact}
Let $p_0<p_1<\cdots$ enumerate the primes. Then $\iota(p_n)\to0$, the set $\{0\}\cup\PP$ is compact, $\overline{\PP}\subseteq\{0\}\cup\PP$, and $\dimH\overline{\PP}=0$.
\end{theorem}

\begin{proof}[Proof sketch]
Since $p_n\ge n$, $\log p_n\to\infty$ and $\iota(p_n)\to0$. A convergent sequence together with its limit is compact, hence closed, so $\overline{\PP}\subseteq\{0\}\cup\PP$; that set is countable, so Theorem~\ref{thm:dimH} applies.
\end{proof}

\subsection{The total length is $1/\log 2$}

\begin{theorem}[Telescoping Length Identity]\label{thm:tel}
Let $(q_i)_{i\ge0}$ be strictly increasing integers $\ge 2$. Then for all $n$,
\[
\sum_{i=0}^{n-1} d(q_i,q_{i+1}) = \iota(q_0)-\iota(q_n) \le \frac{1}{\log 2}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:anti} each term equals $\iota(q_i)-\iota(q_{i+1})$, so the sum telescopes. Since $q_0\ge2$, $\iota(q_0)\le1/\log 2$, and $\iota(q_n)>0$.
\end{proof}

\begin{theorem}[Total Length Theorem]
With $p_0=2<p_1=3<\cdots$ the primes in order,
\[
\lim_{n\to\infty}\sum_{i=0}^{n-1}d(p_i,p_{i+1})=\frac{1}{\log 2}=1.442695\ldots
\]
\end{theorem}

\begin{proof}[Proof sketch]
The partial sum equals $1/\log2-\iota(p_n)$ by Theorem~\ref{thm:tel}, and $\iota(p_n)\to0$ by Theorem~\ref{thm:compact}.
\end{proof}

\begin{remark}
This refutes heuristic (a). The walk along the primes is monotone, so its length telescopes to a universal constant depending only on the starting point $2$. Moreover $\sum_p 1/(p\log p)$ converges; the divergent series of this shape is $\sum_{p\le x}1/p\sim\log\log x$, and the extra factor $1/\log p$ makes all the difference. The prime fractal is rectifiable of finite length.
\end{remark}

\subsection{No dust: every point is isolated}

\begin{lemma}[Finiteness above any height]\label{lem:height}
For $t>0$ the set $\{p \text{ prime}:\iota(p)\ge t\}$ is contained in $\{p\le e^{1/t}\}$, hence finite.
\end{lemma}

\begin{theorem}[Isolation Theorem]\label{thm:iso}
Every $x\in\PP$ is isolated: there is $\varepsilon>0$ such that the only point of $\PP$ within distance $\varepsilon$ of $x$ is $x$. The same holds for $\TT$ and $\II$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $x=\iota(q)>0$. By Lemma~\ref{lem:height} the set $F$ of points of $\PP$ at height $\ge x/2$, with $x$ removed, is finite, hence closed; its complement is an open neighbourhood of $x$ containing some ball $B(x,\varepsilon_0)$. Put $\varepsilon=\min(\varepsilon_0,x/2)$. A point of $\PP$ within $\varepsilon$ of $x$ has height $>x/2$ and avoids $F$, hence equals $x$. Subsets inherit isolation.
\end{proof}

\begin{theorem}[Accumulation criterion]\label{thm:acc}
For any set $T$ of primes, $0\in\overline{\iota(T)}$ if and only if $T$ is infinite.
\end{theorem}

\begin{proof}[Proof sketch]
If $T$ is finite, $\iota(T)$ is a finite set of positive numbers, closed and bounded away from $0$. If $T$ is infinite, for each $\varepsilon>0$ pick $p\in T$ with $p>e^{1/\varepsilon}$; then $\iota(p)<\varepsilon$.
\end{proof}

\begin{corollary}[Twin primes as a metric statement]
There are infinitely many twin primes if and only if $0\in\overline{\TT}$.
\end{corollary}

This is a faithful but purely topological reformulation, concerning a single point of $\mathbb{R}$; a single point contributes to no dimension. With $\dimH\TT=0$ unconditionally and every point of $\TT$ isolated, the conjectured ``twin prime dust'' does not exist.

\begin{theorem}[Twin Scale Theorem]
For every integer $p\ge2$, $\displaystyle d(p,p+2)\le\frac{2}{p(\log p)^2}$.
\end{theorem}

\begin{proof}[Proof sketch]
With $a=\log p$, $b=\log(p+2)$ we have $d(p,p+2)=\frac1a-\frac1b=\frac{b-a}{ab}$. Since $\log(1+u)\le u$ with $u=2/p$, the numerator is $b-a=\log(1+2/p)\le 2/p$; and $ab\ge a^2=(\log p)^2$.
\end{proof}

The heuristic scale $\sim 1/(p\log p)$ overestimates by a factor $\log p$: twins are even closer, hence even less able to spread the set out.

\section{Arithmetic input: an explicit Chebyshev lower bound}

\begin{theorem}[Chebyshev-type lower bound]\label{thm:cheb}
For every integer $n\ge 8$,
\[
n\le 8\,\pi(n)\log n,\qquad\text{equivalently}\qquad \pi(n)\ge\frac{n}{8\log n}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Let $C_n=\binom{2n}{n}$.
\begin{enumerate}
\item $4^n<n\,C_n$ for $n\ge1$, since $4^n=\sum_{k=0}^{2n}\binom{2n}{k}$ is a sum of $2n+1$ terms each at most $C_n$, refined by grouping the extreme terms.
\item Each prime power dividing $C_n$ satisfies $p^{v_p(C_n)}\le 2n$, and only primes $p\le 2n$ occur, so $C_n=\prod_{p\le2n}p^{v_p(C_n)}\le(2n)^{\pi(2n)}$.
\item Hence $4^n<n(2n)^{\pi(2n)}$, i.e.\ $n\log4\le\log n+\pi(2n)\log(2n)$.
\item For $n\ge4$, $\log n\le\pi(2n)\log(2n)$ (as $\pi(2n)\ge1$ and $\log n\le\log 2n$), so $n\log 4\le 2\pi(2n)\log(2n)$; since $\log4>1$ this gives $2n\le 4\pi(2n)\log(2n)$, the claim with constant $4$ for even arguments.
\item Odd $n\ge9$ follow by monotonicity of $\pi$ and $\log$, passing from $n-1$ to $n$ and absorbing the loss into the constant $8$.
\end{enumerate}
\end{proof}

The constant $8$ is far from optimal but is explicit, elementary, and sufficient: constants vanish on the logarithmic scale that defines dimension.

\section{The box-counting dimension is exactly $1$}

\begin{definition}[Grid box count]
For $m\in\mathbb{N}$ the boxes of scale $1/m$ are $[k/m,(k+1)/m)$, $k\in\mathbb{N}$; a point $x\ge0$ lies in the box with index $\lfloor mx\rfloor$. Set
\[
\beta_m(p)=\lfloor m\iota(p)\rfloor=\left\lfloor\frac{m}{\log p}\right\rfloor,\qquad
N(m)=\#\{\beta_m(p): p \text{ prime}\},
\]
and for $S\subseteq[0,\infty)$ put $N_S(m)=\#\{\lfloor mx\rfloor: x\in S\}$, so $N(m)=N_{\PP}(m)$.
\end{definition}

\begin{definition}[Box dimensions]
$\overline{\dim}_B\PP=\limsup_{m\to\infty}\log N(m)/\log m$ and $\underline{\dim}_B\PP=\liminf_{m\to\infty}\log N(m)/\log m$.
\end{definition}

\begin{proposition}\label{prop:ceil}
For all $m$, $1\le N(m)\le 2m+1$.
\end{proposition}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:loc} every point of $\PP$ lies in $[0,2]$, so $\beta_m(p)\le 2m$; nonemptiness follows from $p=2$.
\end{proof}

\begin{lemma}[Logarithmic separation]\label{lem:sep}
For integers $2\le p<q$, $\log q-\log p\ge \dfrac{1}{2p}$.
\end{lemma}

\begin{proof}[Proof sketch]
Put $u=1/(2p)\le1/4$. From $e^{-u}\ge1-u$ we get $e^{u}\le 1/(1-u)$, so $p\,e^{u}\le p/(1-u)=2p^2/(2p-1)\le p+1\le q$, the middle inequality being equivalent to $2p^2\le 2p^2+p-1$. Taking logarithms of $pe^u\le q$ gives $\log p+u\le\log q$.
\end{proof}

\begin{theorem}[Box Separation Theorem]\label{thm:boxsep}
Let $Y\ge2$ and $m$ satisfy $2Y(\log Y)^2\le m$. Then for all integers $2\le p<q\le Y$ one has $\beta_m(q)<\beta_m(p)$; in particular $\beta_m$ is injective on the integers (hence on the primes) in $[2,Y]$.
\end{theorem}

\begin{proof}[Proof sketch]
With $a=\log p$, $b=\log q$, $L=\log Y$ we have $0<a<b\le L$ and, by Lemma~\ref{lem:sep},
\[
m\left(\frac1a-\frac1b\right)=m\,\frac{b-a}{ab}\ \ge\ \frac{m}{2p\,ab}\ \ge\ \frac{m}{2YL^2}\ \ge\ 1 .
\]
Hence $m\iota(q)+1\le m\iota(p)$; applying $\lfloor\cdot\rfloor$, which is monotone and satisfies $\lfloor t+1\rfloor=\lfloor t\rfloor+1$ for $t\ge0$, gives $\beta_m(q)<\beta_m(p)$.
\end{proof}

\begin{corollary}\label{cor:pi}
If $2Y(\log Y)^2\le m$ then $N(m)\ge\pi(Y)$.
\end{corollary}

\begin{theorem}[Arithmetic lower bound on the box count]\label{thm:low}
For all sufficiently large $m$, $\displaystyle N(m)\ge\frac{m}{16(\log m)^4}$.
\end{theorem}

\begin{proof}[Proof sketch]
Write $L=\log m$ and assume $L\ge2$ and $16L^3\le m$ (both hold eventually since $\log^k m=o(m)$). Take $Y=\lfloor m/L^3\rfloor$, the largest scale the separation hypothesis tolerates. Then $YL^3\le m<(Y+1)L^3$, whence $Y\ge15$ and $Y\le m$, so $\log Y\le L$ and
\[
2Y(\log Y)^2\le 2YL^2\le YL^3\le m,
\]
using $L\ge2$. Corollary~\ref{cor:pi} gives $N(m)\ge\pi(Y)$, and Theorem~\ref{thm:cheb} (applicable as $Y\ge8$) gives $Y\le 8\pi(Y)\log Y\le 8\pi(Y)L$. Finally $m\le 2YL^3$, so
\[
m\le 2YL^3\le 16\,\pi(Y)L^4\le 16\,N(m)L^4 . \qedhere
\]
\end{proof}

\begin{theorem}[Box Dimension Theorem]\label{thm:box}
$\displaystyle\lim_{m\to\infty}\frac{\log N(m)}{\log m}=1$, hence $\overline{\dim}_B\PP=\underline{\dim}_B\PP=1$.
\end{theorem}

\begin{proof}[Proof sketch]
From $N(m)\le 2m+1\le 3m$ we get $\log N(m)/\log m\le 1+\log3/\log m$. From Theorem~\ref{thm:low}, eventually
\[
\frac{\log N(m)}{\log m}\ \ge\ 1-\frac{\log 16}{\log m}-4\,\frac{\log\log m}{\log m}.
\]
Both bounds tend to $1$; squeeze.
\end{proof}

\begin{corollary}[Dimension irregularity]
$\dimH\PP=0<1=\overline{\dim}_B\PP$.
\end{corollary}

The gap is maximal for a subset of $\mathbb{R}$. In particular $\PP$ is not Ahlfors regular and is not the attractor of a self-similar iterated function system satisfying the open set condition, since for such sets the two dimensions coincide. The slogan ``the primes are a fractal curve'' is false in the strongest available sense.

\section{Refinements: ceiling, defect, robustness, blindness}

\begin{theorem}[Universal Ceiling]\label{thm:univ}
Let $S\subseteq[0,c]$ with $c>0$. Then $N_S(m)\le\lfloor cm\rfloor+1$ and, for every $\varepsilon>0$, eventually $\log N_S(m)/\log m\le 1+\varepsilon$.
\end{theorem}

\begin{proof}[Proof sketch]
Every $x\in S$ has $\lfloor mx\rfloor\le\lfloor cm\rfloor$, so at most $\lfloor cm\rfloor+1$ indices occur; then $\log N_S(m)\le\log m+O(1)$.
\end{proof}

\begin{corollary}
The conjectured value $1+\varepsilon$ with $\varepsilon>0$ is impossible --- not because of any property of the primes, but because $\PP$ is a bounded subset of a one-dimensional space. The same ceiling applies to Hausdorff dimension.
\end{corollary}

\begin{theorem}[Logarithmic Defect Theorem]\label{thm:defect}
For all sufficiently large $m$, $N(m)\le 5m/\log m$. Consequently $N(m)/m\to0$: the one-dimensional Minkowski content of $\PP$ is zero.
\end{theorem}

\begin{proof}[Proof sketch]
Split the primes at $m$. Primes $p\le m$ contribute at most $\pi(m)\le 2.4\,m/\log m$ distinct indices (Chebyshev's upper bound, valid for large $m$). Primes $p>m$ have $\iota(p)<1/\log m$, so $\beta_m(p)\le\lfloor m/\log m\rfloor$, contributing at most $\lfloor m/\log m\rfloor+1\le 2m/\log m$ further indices. Adding gives $N(m)\le 4.4\,m/\log m+O(1)\le 5m/\log m$ eventually, and dividing by $m$ gives $N(m)/m\le 5/\log m\to0$.
\end{proof}

Combining Theorems~\ref{thm:low} and~\ref{thm:defect},
\[
\frac{m}{16(\log m)^4}\ \le\ N(m)\ \le\ \frac{5m}{\log m}\qquad(m\text{ large}).
\]
A true interval of length $2$ meets $\asymp m$ boxes; $\PP$ meets a factor $\log m$ fewer. This is the precise sense in which the primes ``fill out a line'': to first logarithmic order, while carrying zero length. Equivalently, whenever $N(m)\asymp m/\log m$,
\[
\frac{\log N(m)}{\log m}=1-\frac{\log\log m}{\log m}+O\!\left(\frac{1}{\log m}\right),
\]
so the dimension is approached from below at rate $\log\log m/\log m$. This explains why numerical box-counting on primes up to $10^7$ or $10^{12}$ reports values near $0.84$--$0.88$ rather than $1.00$: the convergence is logarithmically slow by theorem, and the observed deviation is precisely $\log\log m/\log m$.

\begin{theorem}[Cover comparison]\label{thm:cover}
Let $S\subseteq[0,\infty)$ and let $I$ be a finite set of reals with $S\subseteq\bigcup_{c\in I}[c,c+1/m]$. Then $N_S(m)\le 2\,\#I$.
\end{theorem}

\begin{proof}[Proof sketch]
An interval of length $1/m$ meets at most two grid boxes: if $x\in[c,c+1/m]$ then $\lfloor mc\rfloor\le\lfloor mx\rfloor\le\lfloor mc\rfloor+1$. Hence the occupied indices are covered by the $2\#I$ values $\lfloor mc\rfloor+j$, $c\in I$, $j\in\{0,1\}$.
\end{proof}

\begin{corollary}[Covering form of the lower bound]
For every $\varepsilon>0$, eventually in $m$: every finite cover of $\PP$ by intervals of length $1/m$ has at least $m^{1-\varepsilon}$ members. The value $1$ is intrinsic to the set, not to the grid.
\end{corollary}

\begin{theorem}[Dimension Blindness]\label{thm:blind}
For the integer fractal $\II=\{1/\log n: n\ge2\}$,
\[
\dimH\II=0=\dimH\PP,\qquad
\lim_{m\to\infty}\frac{\log N_{\II}(m)}{\log m}=1=\lim_{m\to\infty}\frac{\log N(m)}{\log m}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The Hausdorff statement is Theorem~\ref{thm:dimH}. The upper bound $N_{\II}(m)\le 2m+1$ is Proposition~\ref{prop:ceil} verbatim. For the lower bound the separation Theorem~\ref{thm:boxsep} applies to all integers $\ge2$, so the integers $2,\dots,Y$ occupy $Y-1$ distinct boxes as soon as $2Y(\log Y)^2\le m$; taking $Y=\lfloor m/(\log m)^3\rfloor$ gives $\log(Y-1)/\log m\to1$. No Chebyshev bound is needed.
\end{proof}

\begin{corollary}[Structural impossibility]
No dimension of the logarithmic embedding --- Hausdorff or box --- can distinguish the primes from the full set of integers $\ge2$. In particular none can encode the twin prime conjecture, nor any statement about prime density.
\end{corollary}

The only place primes differ from integers in this geometry is the second-order term: $N_{\II}(m)\asymp m$ in the relevant regime, whereas $N(m)\asymp m/\log m$. Density survives in the \emph{count}, not in the \emph{dimension}.

\section{Algorithms and numerical evidence}

Exact computation of $N(m)$ is subtle. Box index $k\ge1$ is occupied precisely when the interval $I_k=(e^{m/(k+1)},e^{m/k}]$ contains a prime, and index $0$ (all $p>e^{m}$) is always occupied. For small $k$ these intervals are astronomically large, so brute enumeration is impossible. The practical algorithm splits at a sieve limit $X$:

\begin{enumerate}
\item \textbf{Sieve head.} Enumerate all primes $p\le X$ and collect the exact index set $H=\{\lfloor m/\log p\rfloor: p\le X\}$.
\item \textbf{Tail prediction.} For each $k<m/\log X$ decide occupancy of $I_k$ by the Prime Number Theorem estimate $\pi(e^{m/k})-\pi(e^{m/(k+1)})\approx e^{m/k}k/m-e^{m/(k+1)}(k+1)/m\gg1$, which is overwhelmingly larger than $1$; the tail indices are therefore all occupied.
\item \textbf{Combine.} $N(m)=\#(H\cup\{\text{tail indices}\})$.
\end{enumerate}

The cost is $O(X\log\log X)$ time and $O(X)$ space for the sieve, plus $O(\pi(X)+m/\log X)$ bookkeeping. The head/tail split mirrors the proof of Theorem~\ref{thm:defect}, and is also the structure behind the conjecture $N(m)\log m/m\to1$: the tail contributes $\approx m/\log X$ boxes and the head $\approx\pi(X)$, and optimising at $X\approx m$ makes the tail $\sim m/\log m$ dominant.

Numerically, $\log N(m)/\log m$ rises slowly toward $1$ (typically $0.80$--$0.90$ over accessible $m$), while $N(m)\log m/m$ stays in a narrow band around $1.3$--$1.7$ and drifts downward. Both are exactly as Theorems~\ref{thm:box} and~\ref{thm:defect} predict. The cumulative $d$-length along the primes converges to $1/\log 2$ with deficit $1/\log p_n$; observed twin distances sit under $2/(p(\log p)^2)$, roughly a factor $\log p$ below the heuristic $1/(p\log p)$; and integer-fractal box counts track prime-fractal box counts closely on the logarithmic scale, illustrating dimension blindness.

\section{Discussion}

\subsection{Why the conjecture failed, in three layers}

\emph{Superficially}: the motivating length computation was wrong. The $d$-length telescopes to $1/\log2$, and the series that was supposed to diverge converges.

\emph{Structurally}: any subset of the line has box dimension at most $1$ and, if countable, Hausdorff dimension exactly $0$. Both hypotheses hold for $\PP$ unconditionally, leaving no room for a twin-prime-dependent $\varepsilon$.

\emph{Conceptually}: dimension is an extremely lossy functional, seeing only the exponential growth rate of covering numbers. Arithmetic information lives in constants and logarithmic factors, which the double compression in $\log N(m)/\log m$ destroys. Dimension Blindness makes this quantitative: primes and integers, radically different arithmetically, are indistinguishable dimensionally.

\subsection{What replaced it}

The pair $(\dimH,\dim_B)=(0,1)$ is the extreme case of dimension irregularity in $\mathbb{R}$, and $\PP$ is a clean, explicitly arithmetic example. Its finite length $1/\log2$ makes it a rectifiable set whose box dimension is nonetheless $1$ --- a good counterexample to the intuition that box dimension $1$ implies positive length. And $N(m)\asymp m/\log m$ locates the surviving arithmetic precisely, as a Prime-Number-Theorem-shaped second-order term.

There is also a methodological lesson: box-counting experiments on arithmetic sets converge at rate $\log\log m/\log m$, effectively non-convergent over accessible scales. Reducing the deviation below $0.05$ requires $m$ beyond $10^{30}$. Reported ``measured dimensions'' of arithmetic sets should be read accordingly.

\subsection{Open problems}

\begin{conjecture}[Exact Minkowski constant]
$\displaystyle\lim_{m\to\infty}\frac{N(m)\log m}{m}=1$, equivalently $N(m)=(1+o(1))\,m/\log m$.
\end{conjecture}

The heuristic is the head/tail split: tail indices $k\le m/\log X$ are all occupied because $(e^{m/(k+1)},e^{m/k}]$ has ratio $e^{m/(k(k+1))}$ and hence contains a prime, while the head contributes one box per prime $p\le X$. Optimising at $X=m$ makes the tail $\sim m/\log m$ and the head $o(m/\log m)$, so the constant $1$ comes from the tail, independently of $\pi$. Bertrand's postulate handles $k\lesssim\sqrt m$; any short-interval prime-existence result extends this to the full range. The bracket $m/(16(\log m)^4)\le N(m)\le 5m/\log m$ is established here, and numerics place $N(m)\log m/m$ in $[1.26,1.75]$ and decreasing.

\begin{conjecture}[Logarithmic defect as a second-order invariant]
Define $\displaystyle\delta(S)=\lim_{m\to\infty}\left(1-\frac{\log N_S(m)}{\log m}\right)\frac{\log m}{\log\log m}$. Then $\delta(\PP)=1$, $\delta=0$ for every self-similar set of dimension $1$, and $\delta(\II)=1$.
\end{conjecture}

The rate at which the box dimension approaches $1$ is a genuine invariant, invisible to the dimension, separating ``arithmetically thin'' dimension-one sets from geometric ones --- and it is exactly what box-counting experiments measure.

\begin{conjecture}[Invisibility of twin primes]
For a subfamily $T$ of primes that is not too sparse, the subfractal $\iota(T)$ again has box dimension $1$; identify the exact density threshold at which the box dimension drops below $1$.
\end{conjecture}

Under the Hardy--Littlewood twin prime conjecture, $\TT$ would satisfy $N_{\TT}(m)\asymp m/\log m$ up to constants and hence have box dimension $1$, equal to that of the primes and of the integers. Determining $\dim_B\TT$ unconditionally would complete the picture.

Further directions: compute $\lim N(m)\log m/m$ for other arithmetic sequences (squares, smooth numbers, primes in progressions) and determine which sequences $\delta$ distinguishes; study lenses $\iota_f(n)=1/f(n)$ for slowly growing $f$ and find for which $f$ the box dimension falls in $(0,1)$, the logarithm sitting exactly at the saturation boundary; and examine the packing and Assouad dimensions of $\PP$, the latter being a sensitive invariant of monotone sequences converging to $0$.

\section{Conclusion}

Under the logarithmic lens $p\mapsto1/\log p$, the primes form a bounded, countable, rectifiable set of total length exactly $1/\log2$, every point of which is isolated. Its Hausdorff dimension is $0$; its box-counting dimension is exactly $1$; its one-dimensional Minkowski content is $0$, with $N(m)=\Theta(m/\log m)$. The same three values hold verbatim for all integers $\ge2$, so no dimension here can see primality, and ``dimension $=1+\varepsilon(\text{twin primes})$'' is impossible: no bounded subset of $\mathbb{R}$ has box dimension above $1$, and no countable set has positive Hausdorff dimension. What remains is sharper than what was conjectured: an explicit example of maximal dimension irregularity on the line, with the discarded arithmetic reappearing one order down, in the constant of $N(m)\log m/m$ and in the $\log\log m/\log m$ rate of convergence.

