"""Head-tail box counting for the logarithmic prime embedding."""

from __future__ import annotations

import math
from typing import List, Set


def sieve_primes(limit: int) -> List[int]:
    """All primes <= limit by the sieve of Eratosthenes, O(limit log log limit)."""
    if limit < 2:
        return []
    flags = bytearray([1]) * (limit + 1)
    flags[0] = flags[1] = 0
    for p in range(2, int(limit**0.5) + 1):
        if flags[p]:
            flags[p * p :: p] = bytearray(len(flags[p * p :: p]))
    return [i for i in range(limit + 1) if flags[i]]


def box_index(m: int, n: int) -> int:
    """Index of the box of width 1/m holding the point 1/log n."""
    return int(math.floor(m / math.log(n)))


def occupied_head(m: int, primes: List[int]) -> Set[int]:
    """Exact occupied indices contributed by the sieved primes."""
    return {box_index(m, p) for p in primes}


def tail_threshold(m: int, sieve_limit: int) -> int:
    """
    Largest index k whose defining interval (exp(m/(k+1)), exp(m/k)] extends
    beyond the sieve limit X.  Every k in {0, ..., k_max} is occupied: the
    interval has ratio exp(m/(k(k+1))), which is astronomically wide, so the
    Prime Number Theorem estimate for the primes it contains is enormous.
    """
    return int(math.floor(m / math.log(sieve_limit)))


def box_count(m: int, primes: List[int], sieve_limit: int) -> int:
    """N(m): the number of boxes of width 1/m meeting the prime fractal."""
    occupied = occupied_head(m, primes)
    occupied.update(range(0, tail_threshold(m, sieve_limit) + 1))
    return len(occupied)


def box_dimension_estimate(m: int, primes: List[int], sieve_limit: int) -> float:
    """log N(m) / log m, the finite-scale box-dimension estimate."""
    return math.log(box_count(m, primes, sieve_limit)) / math.log(m)


def minkowski_ratio(m: int, primes: List[int], sieve_limit: int) -> float:
    """N(m) log m / m, conjectured to tend to 1."""
    return box_count(m, primes, sieve_limit) * math.log(m) / m


if __name__ == "__main__":
    X = 1_000_000
    ps = sieve_primes(X)
    print(f"{'m':>10} {'N(m)':>10} {'log N/log m':>13} {'N log m / m':>13}")
    for m in (10, 100, 1_000, 10_000, 100_000, 1_000_000):
        print(f"{m:>10} {box_count(m, ps, X):>10} "
              f"{box_dimension_estimate(m, ps, X):>13.5f} "
              f"{minkowski_ratio(m, ps, X):>13.5f}")
